package com.acttub.actingapi.auth;
import static org.assertj.core.api.Assertions.*; import com.fasterxml.jackson.databind.ObjectMapper; import org.junit.jupiter.api.Test; import org.springframework.boot.test.context.runner.ApplicationContextRunner; import org.springframework.context.annotation.Bean;
class AuthConfigurationTest {private final ApplicationContextRunner runner=new ApplicationContextRunner().withUserConfiguration(AuthConfiguration.class,Mapper.class);@Test void missingOrEmptySecretFailsStartup(){runner.run(context->assertThat(context).hasFailed());runner.withPropertyValues("JWT_SECRET=").run(context->assertThat(context).hasFailed());}@Test void configuredRawSecretBoots(){runner.withPropertyValues("JWT_SECRET=비ASCII-secret").run(context->assertThat(context).hasNotFailed().hasSingleBean(JwtService.class));}static class Mapper{@Bean ObjectMapper objectMapper(){return new ObjectMapper();}}}
